            write_point2(out, p3);
            write_point2(out, p4);
        }
        CadEntity::Dimension { def_point, text_position, measurement, text } => {
            out.push(8);
            write_point2(out, def_point);
            write_point2(out, text_position);
            out.extend_from_slice(&measurement.to_le_bytes());
            write_str_lp(out, text);
        }
    }
