pub(crate) fn enc_node_diff(d: &DrawNodeDiff) -> String {
    match d {
        DrawNodeDiff::Path(p) => format!("P[{},{}]", encode_option(&p.segments, |v| enc_list(v, enc_path_segment)), encode_option(&p.style, |v| encode_option(v, |s| enc_str(s)))),
