pub(crate) fn parse_mesh_snapshot_body(body: &str) -> Result<SemioMeshSnapshot, String> {
    let mut schema = None;
    let mut meshes = Vec::new();
    let mut materials = Vec::new();
    let mut textures = Vec::new();
    for line in body.lines() {
