pub(crate) fn dec_indexed_diff_bin(reader: &mut store::ByteReader<'_>) -> Result<IndexedTripleDiff<SemioValueDiff, SemioValue>, String> {
    let removed_count = reader.read_varint_u64().map_err(|e| e.to_string())?;
