 let DslValue::Array(edges)=member(&mut value,"edges")? else{return Err(invalid("Semio graph edges required"))};for edge in edges{fields(edge,&["id","source","target","kind","label","properties"],&["sourcePort","targetPort"])?;}Ok(value)
}

