    match tag {
        0 => Ok(store::LinkPin::Head),
        1 => Ok(store::LinkPin::Checkpoint { id: read_str_lp(reader)? }),
        2 => {
            let hash = read_str_lp(reader)?;
            let size = reader.read_varint_u64().map_err(|e| e.to_string())?;
